let sources=stored.sources||initialSources,read=stored.read||[],saved=stored.saved||[],profile=stored.profile||{name:'Alex Morgan',username:'alexmorgan',timezone:'America/New_York',location:'Brooklyn, New York',color:'#101010',accent:'#ffffff'};let page='Sources',tab='All updates',query='',kind='All types',network='All platforms',searched=false,selectedSource=null;
const demoMember={id:'member-maya',name:'Maya Chen',initial:'MC',color:'#aaa',type:'Person',bio:'',links:['App','Instagram','Website'],saved:true,member:true,username:'mayachen',presence:'online'};
if(!sources.some(s=>s.id===demoMember.id))sources.push(demoMember);
