let lastActivity=Date.now(),previousPresence=navigator.onLine?'online':'offline',lastOnline=stored.lastOnline||null;
const selfPresence=()=>!navigator.onLine?'offline':document.hidden||Date.now()-lastActivity>=300000?'idle':'online';
const statusLabel=s=>s==='online'?'Online':s==='idle'?'Idle':'Offline';
const presenceDot=s=>`<span class="presence-dot ${s}" role="img" aria-label="${statusLabel(s)}" title="${statusLabel(s)}"></span>`;
function memberPresence(source){const state=source.presence||'offline';return `<span class="member-presence">${presenceDot(state)}${statusLabel(state)}${state==='offline'&&source.lastOnline?' · Last online '+esc(new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(source.lastOnline))):''}</span>`}
function refreshPresence(){const current=selfPresence();if(current==='offline'&&previousPresence!=='offline'){lastOnline=new Date().toISOString();persist()}previousPresence=current;document.querySelectorAll('.own-card-presence').forEach(e=>e.innerHTML=memberPresence({presence:current,lastOnline}));document.querySelectorAll('[data-self-presence]').forEach(e=>{e.innerHTML=presenceDot(selfPresence());e.setAttribute('title',statusLabel(current)+(current==='offline'&&lastOnline?' · Last online '+new Date(lastOnline).toLocaleString():''))})}
for(const event of ['pointerdown','keydown','pointermove','touchstart'])document.addEventListener(event,()=>{lastActivity=Date.now();refreshPresence()},{passive:true});
for(const event of ['online','offline','pageshow'])window.addEventListener(event,refreshPresence);document.addEventListener('visibilitychange',refreshPresence);setInterval(refreshPresence,15000);
