const persist=()=>{try{localStorage.setItem('daily-mockup',JSON.stringify({sources,read,saved,profile,conversations,lastOnline,settings,ownPosts,postDraft,categories,publishingDraft}))}catch{toast('Storage is full. Try a smaller image.')}};
const avatar=s=>`<span class="avatar" style="background:${s.color};color:#111">${esc(s.initial)}</span>`;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',2600)}
const emptyView=(p='Sources',source=null)=>({page:p,query:'',kind:'All types',network:'All platforms',searched:false,selectedSource:source,tab:'All updates',sourceMode:'Updates',draft:'',scroll:0,opened:[]});
let workspaceTabs=[{key:'Sources',...emptyView()}],activeKey='Sources';
function saveView(){announceTyping(false);cancelRecording();document.querySelector('.emoji-picker')?.remove();const t=workspaceTabs.find(t=>t.key===activeKey);if(!t)return;Object.assign(t,{page,query,kind,network,searched,selectedSource,tab,sourceMode,scroll:window.scrollY,opened:[...document.querySelectorAll('details[open][data-post]')].map(e=>e.dataset.post)});const input=document.querySelector('#search-input');if(input)t.draft=input.value;}
function activateTab(key){saveView();const t=workspaceTabs.find(t=>t.key===key);if(!t)return;activeKey=key;({page,query,kind,network,searched,selectedSource,tab,sourceMode}=t);render();const input=document.querySelector('#search-input');if(input)input.value=t.draft;for(const id of t.opened||[]){const d=document.querySelector(`[data-post="${id}"]`);if(d)d.open=true}window.scrollTo(0,t.scroll||0);document.querySelector('[aria-selected="true"]')?.scrollIntoView({block:'nearest',inline:'nearest'});}
function openView(view,key){saveView();if(!workspaceTabs.some(t=>t.key===key))workspaceTabs.push({key,...view});activateTab(key)}
function go(p){openView(emptyView(p,p==='Source'?selectedSource:null),p==='Source'?'Source:'+selectedSource:p)}
function searchView(){const q=document.querySelector('#search-input').value.trim(),k=document.querySelector('#kind')?.value||'All types',n=document.querySelector('#network')?.value||'All platforms';const has=!!q||k!=='All types'||n!=='All platforms';if(!has)return go('Search');const key='Search:'+JSON.stringify([q.toLocaleLowerCase().replace(/\s+/g,' '),k,n]);openView({...emptyView('Search'),query:q,draft:q,kind:k,network:n,searched:true},key)}
function closeTab(key){const i=workspaceTabs.findIndex(t=>t.key===key);if(i<0)return;saveView();workspaceTabs.splice(i,1);if(!workspaceTabs.length)workspaceTabs.push({key:'Sources',...emptyView()});if(activeKey===key){activeKey='';activateTab(workspaceTabs[Math.min(i,workspaceTabs.length-1)].key)}else render()}
function tabsView(){return `<div class="workspace-tabs" role="tablist" aria-label="Open views">${workspaceTabs.map((t,i)=>{const label=t.page==='Source'?sources.find(s=>s.id===t.selectedSource)?.name||'Source':t.searched?t.query||[t.kind,t.network].filter(x=>!x.startsWith('All ')).join(' · '):t.page;return `<div class="workspace-tab ${t.key===activeKey?'selected':''}"><button role="tab" aria-selected="${t.key===activeKey}" aria-controls="view-panel" id="workspace-tab-${i}" tabindex="${t.key===activeKey?0:-1}" data-workspace="${esc(t.key)}" title="${esc(label)}">${icon(t.page==='Search'?'search':t.page==='Saved'?'save':t.page==='Read'?'check':'sources')}<span>${esc(label)}</span></button><button class="close-tab" data-close-tab="${esc(t.key)}" aria-label="Close ${esc(label)} tab">${icon('close')}</button></div>`}).join('')}</div><button class="new-search" id="new-search" aria-label="New source search" title="New source search">${icon('plus')}</button>`}
function bindWorkspace(){document.querySelectorAll('[data-workspace]').forEach(e=>{e.onclick=()=>activateTab(e.dataset.workspace);e.onkeydown=event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const i=workspaceTabs.findIndex(t=>t.key===e.dataset.workspace);const next=event.key==='Home'?0:event.key==='End'?workspaceTabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+workspaceTabs.length)%workspaceTabs.length;activateTab(workspaceTabs[next].key);document.querySelector('[role="tab"][aria-selected="true"]').focus()}}});document.querySelectorAll('[data-close-tab]').forEach(e=>e.onclick=()=>closeTab(e.dataset.closeTab));document.querySelector('#new-search').onclick=()=>{go('Search');document.querySelector('#search-input').focus()}}
function render(){cancelRecording();document.querySelector('.emoji-picker')?.remove();const names=['Sources','Saved','Read','Files'];document.querySelector('#app').innerHTML=`<div class="layout"><aside class="sidebar"><nav class="nav">${names.map((n,i)=>`<button class="${page===n||(page==='Today'||page==='Source')&&n==='Sources'?'active':''}" ${n==='Files'?'aria-disabled="true"':`data-page="${n}"`}>${icon(['sources','save','check','folder'][i])}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="btn primary post-trigger" id="new-post">${icon('plus')} Post</button><div class="profile-actions"><button class="profile-trigger" data-page="Profile"><span class="self-avatar"><span class="avatar">${profile.pfp?`<img class="avatar" src="${profile.pfp}" alt="">`:esc(profile.name.slice(0,1))}</span><span data-self-presence>${presenceDot(selfPresence())}</span></span><span class="profile-name">${esc(profile.name)}${settings.showUsername?`<small>@${esc(profile.username)}</small>`:''}</span></button><button type="button" id="availability-toggle" aria-label="Open to" aria-haspopup="menu" aria-expanded="false" aria-controls="availability-menu"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button></div><div id="availability-menu" role="menu" aria-label="Open to" hidden>${availabilityChoices.map(([value,label])=>`<button type="button" role="menuitemradio" aria-checked="${(profile.openTo||'unavailable')===value}" data-availability="${value}">${label}${(profile.openTo||'unavailable')===value?icon('check'):''}</button>`).join('')}</div>${profile.openTo&&profile.openTo!=='unavailable'?`<span class="availability-summary">Open to ${availabilityChoices.find(([v])=>v===profile.openTo)?.[1].toLowerCase()||''}</span>`:''}${mediaControlButtons()}</div></aside><main class="main"><div class="workspace-chrome"><header class="topbar"><button class="mobile-toggle" aria-label="Open navigation" id="mobile-menu">${icon('menu')}</button>${tabsView()}</header><form id="search-form" class="searchbox">${icon('search')}<input id="search-input" aria-label="Search sources" placeholder="Name or platform" value="${esc(query)}"><button type="button" class="filters-toggle" id="filters-toggle" aria-label="Filters" aria-expanded="false" aria-controls="search-filters">${icon('filters')}<span>Filters</span><span id="filter-count" hidden></span></button><button type="button" id="reverse" aria-label="Search by image">${icon('image')}</button><button type="submit" class="btn" aria-label="Run search">${icon('arrow')}</button></form><div class="advanced search-filters" id="search-filters" hidden><select id="kind" aria-label="Source type">${['All types','Person','Organization','Publication'].map(n=>`<option ${kind===n?'selected':''}>${n}</option>`).join('')}</select><select id="network" aria-label="Platform">${['All platforms','Instagram','YouTube','Bandcamp','Bluesky','Tumblr','Flickr','SoundCloud','Website','Custom / legacy link'].map(n=>`<option ${network===n?'selected':''}>${n}</option>`).join('')}</select></div></div><section id="view-panel" role="tabpanel" aria-labelledby="workspace-tab-${workspaceTabs.findIndex(t=>t.key===activeKey)}">${content()}</section></main></div>`;bind()}
function isEnabled(p){const s=sources.find(s=>s.id===p.source);return s?.saved&&!s.disabled?.includes(s.links.indexOf(p.platform))}
function content(){if(page==='Source')return sourceView();if(page==='Profile')return profileView();if(page==='Settings')return settingsView();if(page==='Search'||page==='Sources')return sourcesView();let list=posts.filter(isEnabled);if(page==='Source')list=list.filter(p=>p.source===selectedSource);if(page==='Saved')list=list.filter(p=>saved.includes(p.id));if(page==='Read')list=list.filter(p=>read.includes(p.id));if(tab==='Unread')list=list.filter(p=>!read.includes(p.id));return `<div class="page-title"><h1>${page==='Source'?esc(sources.find(s=>s.id===selectedSource)?.name):page}</h1>${page==='Source'?`<button class="btn" data-source="${selectedSource}">About & links</button>`:''}</div><div class="filters">${['All updates','Unread'].map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}<button class="filter-right" id="mark-all">Mark all as read</button></div>${list.length?list.map(postView).join(''):'<div class="empty">No updates</div>'}`}
function postView(p){const source=sources.find(s=>s.id===p.source);return `<details class="update" data-post="${p.id}"><summary><span class="update-source">${page==='Source'?esc(p.platform):`${esc(source.name)}<small>${p.platform}</small>`}</span><span class="update-time">${p.time}</span>${icon('plus')}</summary><div class="update-content"></div></details>`}
function expandedPost(p){return `<article class="post"><div class="post-body">${p.title?`<h2>${esc(p.title)}</h2>`:''}${p.text?`<p>${esc(p.text)}</p>`:''}${p.description?`<p class="post-description">${esc(p.description)}</p>`:''}${pollMarkup(p)}<div class="post-files">${(p.attachments||[]).map(a=>((a.type?.startsWith('video/')||a.type?.startsWith('audio/'))?`<${a.type.startsWith('video/')?'video':'audio'} class="post-media-preview" data-post-media="${a.id}" controls preload="metadata"></${a.type.startsWith('video/')?'video':'audio'}>`:'')+attachmentView(a)).join('')}</div>${p.type==='live'?'<span class="publish-note">Stream announcement</span>':''}</div>${p.image?`<img class="post-image" src="${p.image}" alt="${esc(p.alt)}">`:''}${openSourcePost(p)}<footer class="post-footer"><div class="post-actions"><button data-read="${p.id}">${icon('check')}${read.includes(p.id)?'Mark unread':'Mark read'}</button><button data-save="${p.id}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} update" style="color:${saved.includes(p.id)?'#fff':'inherit'}">${icon('save')}</button>${p.url?`<a href="${p.url}" target="_blank" rel="noreferrer" aria-label="Open original">${icon('out')}</a>`:''}</div></footer></article>`}
function sourcesView(){const isSearch=page==='Search';return `<div class="page-title"><h1>${page}</h1><button class="btn" id="add-source">${icon('plus')} Import link</button></div>${!isSearch?`<div class="sources-toolbar"><button class="btn today-option" data-page="Today">${icon('home')} Today ${icon('arrow')}</button><button class="btn" id="add-category">${icon('plus')} Category</button></div>`:''}<div id="source-results">${sourceResults()}</div>`}
function sourceResults(){if(page==='Search'&&!searched)return '';const list=sources.filter(s=>(page!=='Sources'||s.saved)&&(!query||`${s.name} ${s.links.join(' ')}`.toLowerCase().includes(query.toLowerCase()))&&(kind==='All types'||s.type===kind)&&(network==='All platforms'||(network==='Custom / legacy link'?s.customLinks?.length:s.links.includes(network))));return page==='Sources'?categoryTree(list):`<div class="source-grid">${list.map(sourceRow).join('')}</div>${!list.length?'<div class="empty">No sources</div>':''}`}
function profileView(){return `<div class="page-title"><div><h1>Profile</h1></div></div><section class="profile-card" style="background:${profile.color}"><div class="banner" ${profile.banner?`style="background-image:url('${profile.banner}')"`:''}><button class="btn upload-banner" id="banner-upload">${icon('image')} Change banner</button></div><div class="profile-content"><button class="profile-avatar" id="pfp-upload" style="background:${profile.accent}" aria-label="Upload profile picture">${profile.pfp?`<img src="${profile.pfp}" alt="Your profile picture">`:esc(profile.name.slice(0,1))}</button><div class="own-card-presence">${memberPresence({presence:selfPresence(),lastOnline})}</div>${profile.openTo&&profile.openTo!=='unavailable'?`<div class="card-availability">Open to ${availabilityChoices.find(([v])=>v===profile.openTo)?.[1].toLowerCase()}</div>`:''}<input class="editable name" data-profile="name" aria-label="Display name" value="${esc(profile.name)}" maxlength="50"><input class="editable handle" data-profile="username" aria-label="Username" value="${esc(profile.username)}" maxlength="30"><div class="profile-fields"><label>TIMEZONE<input type="text" data-profile="timezone" value="${esc(profile.timezone)}" placeholder="America/New_York"></label><label>LOCATION<input type="text" data-profile="location" value="${esc(profile.location)}" placeholder="Your city"></label></div><fieldset class="pronoun-field"><legend>Pronouns</legend>${['he/him','she/her','they/them'].map(value=>`<label><input type="radio" name="pronouns" data-profile="pronouns" value="${value}" ${profile.pronouns===value?'checked':''}>${value}</label>`).join('')}</fieldset><div class="color-row"><label for="card-color">Card</label><input id="card-color" type="color" data-profile="color" value="${profile.color}"><label for="accent-color">Accent</label><input id="accent-color" type="color" data-profile="accent" value="${profile.accent}"></div></div></section>`}
function modal(title,body){const m=document.querySelector('#modal');m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button id="close-modal" aria-label="Close">${icon('close')}</button></div>${body}`;m.showModal();document.querySelector('#close-modal').onclick=()=>m.close()}
function sourceModal(id){const s=sources.find(s=>s.id===id);modal(esc(s.name),`${s.member?`<section class="member-profile-card"><div class="member-banner"></div><div class="member-card-content"><span class="member-card-avatar">${esc(s.initial)}</span><div class="member-handle">@${esc(s.username||s.name)}</div>${memberPresence(s)}</div></section>`:s.bio?`<p class="modal-intro">${esc(s.bio)}</p>`:''}<div id="links">${s.links.map((l,i)=>`<label class="link-row"><input type="checkbox" data-link="${i}" ${s.disabled?.includes(i)?'':'checked'}>${esc(l)}</label>`).join('')}</div><form id="custom-link"><input type="url" id="link-url" class="full" placeholder="https://… (any platform or archive)" required aria-label="Custom social link"><button class="btn full">${icon('plus')} Add another link</button></form><button class="btn primary full" id="modal-follow">${s.saved?'Remove from sources':'Add to sources'}</button>`);document.querySelectorAll('[data-link]').forEach(el=>el.onchange=()=>{s.disabled=s.disabled||[];const n=+el.dataset.link;s.disabled=el.checked?s.disabled.filter(x=>x!==n):[...s.disabled,n];persist();render();toast('Connection preference saved')});document.querySelector('#modal-follow').onclick=()=>{s.saved=!s.saved;persist();document.querySelector('#modal').close();render()};document.querySelector('#custom-link').onsubmit=e=>{e.preventDefault();const u=new URL(document.querySelector('#link-url').value);if(!['https:','http:'].includes(u.protocol))return toast('Use an http or https link');s.links.push(u.hostname.replace('www.',''));s.customLinks=s.customLinks||[];s.customLinks.push(u.href);persist();document.querySelector('#modal').close();sourceModal(id);render()}}
function importModal(){modal('Import source',`<form id="import-form"><input type="url" id="import-url" class="full" placeholder="https://…" aria-label="Source URL" required><input type="text" id="import-name" class="full" placeholder="Source name" aria-label="Source name" maxlength="60" required><button class="btn primary full">Add source ${icon('arrow')}</button></form>`);document.querySelector('#import-form').onsubmit=e=>{e.preventDefault();const u=new URL(document.querySelector('#import-url').value);if(!['https:','http:'].includes(u.protocol))return toast('Use an http or https link');const name=document.querySelector('#import-name').value.trim();if(!name)return;sources.push({id:'custom-'+Date.now(),name,initial:name.slice(0,1),color:'#999999',type:'Person',bio:'',links:[u.hostname.replace('www.','')],customLinks:[u.href],saved:true});persist();document.querySelector('#modal').close();go('Sources');toast('Source added')};}
function upload(callback){const f=document.createElement('input');f.type='file';f.onchange=()=>{const file=f.files[0];if(!file)return;const r=new FileReader();r.onload=()=>callback(r.result,file.name);r.onerror=()=>toast('Could not read file');r.readAsDataURL(file)};f.click()}
function bind(){bindPublicationView(document);bindCategories();bindCalls();bindAvailability();bindMediaControls();bindSettingsAndPost();bindMessaging();bindFilters();bindWorkspace();bindSourceOpen();bindUpdates();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceModal(b.dataset.source));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{const n=+b.dataset.read;read=read.includes(n)?read.filter(x=>x!==n):[...read,n];persist();render()});document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const n=+b.dataset.save;const exists=saved.includes(n);saved=exists?saved.filter(x=>x!==n):[...saved,n];persist();render();toast(exists?'Removed from saved':'Saved for later')});document.querySelectorAll('[data-follow]').forEach(b=>b.onclick=()=>{const s=sources.find(s=>s.id===b.dataset.follow);s.saved=!s.saved;persist();render()});['add-source','side-add'].forEach(id=>{const e=document.getElementById(id);if(e)e.onclick=importModal});document.querySelector('#mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');const all=document.querySelector('#mark-all');if(all)all.onclick=()=>{read=[...new Set([...read,...posts.filter(p=>isEnabled(p)&&(page!=='Source'||p.source===selectedSource)&&(page!=='Saved'||saved.includes(p.id))&&(page!=='Read'||read.includes(p.id))).map(p=>p.id)])];persist();render();toast('Marked as read')};const form=document.querySelector('#search-form');if(form)form.onsubmit=e=>{e.preventDefault();searchView()};const rev=document.querySelector('#reverse');if(rev)rev.onclick=()=>modal('Image search',`<button class="btn full" id="reverse-upload">${icon('image')} Choose an image</button><div id="reverse-result"></div>` )||null; if(rev){const old=rev.onclick;rev.onclick=()=>{old();document.querySelector('#reverse-upload').onclick=()=>upload((data,name)=>{document.querySelector('#reverse-result').innerHTML=`<div class="image-result"><img src="${data}" alt="Selected image" style="width:100%;max-height:180px;object-fit:contain"><p>${esc(name)}</p><p>Image search unavailable.</p></div>`;})}}document.querySelectorAll('[data-profile]').forEach(e=>e.oninput=()=>{profile[e.dataset.profile]=e.value;persist();if(e.dataset.profile==='color')document.querySelector('.profile-card').style.background=e.value;if(e.dataset.profile==='accent')document.querySelector('.profile-avatar').style.background=e.value});['banner','pfp'].forEach(k=>{const e=document.querySelector('#'+k+'-upload');if(e)e.onclick=()=>upload(data=>{profile[k]=data;persist();render()})});}
function bindFilters(){const button=document.querySelector('#filters-toggle'),panel=document.querySelector('#search-filters');const refresh=()=>{const count=Number(document.querySelector('#kind').value!=='All types')+Number(document.querySelector('#network').value!=='All platforms');const badge=document.querySelector('#filter-count');badge.textContent=count;badge.hidden=!count;button.classList.toggle('has-filters',!!count)};button.onclick=()=>{panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden))};panel.onkeydown=e=>{if(e.key==='Escape'){panel.hidden=true;button.setAttribute('aria-expanded','false');button.focus()}};panel.querySelectorAll('select').forEach(e=>e.onchange=refresh);refresh()}
function bindResults(){bindCategories();bindMessaging();bindSourceOpen();document.querySelectorAll('#source-results [data-source]').forEach(b=>b.onclick=()=>sourceModal(b.dataset.source));document.querySelectorAll('#source-results [data-follow]').forEach(b=>b.onclick=()=>{const s=sources.find(s=>s.id===b.dataset.follow);s.saved=!s.saved;persist();render()})}
function sourceView(){const source=sources.find(s=>s.id===selectedSource);if(!source)return '<div class="empty">Source unavailable</div>';const list=posts.filter(p=>isEnabled(p)&&p.source===source.id&&(tab!=='Unread'||!read.includes(p.id)));return `<div class="page-title"><h1>${esc(source.name)}</h1><div class="source-header-actions">${source.member&&source.id!=='self'?`<button class="btn" id="start-call">${icon('phone')} Call</button>`:''}<button class="btn" data-source="${source.id}">About & links</button></div></div>${source.member?`<div class="source-modes"><button data-source-mode="Updates" class="${sourceMode==='Updates'?'active':''}">Updates</button>${source.id==='self'?`<button data-source-mode="Scheduled" class="${sourceMode==='Scheduled'?'active':''}">Scheduled</button>`: `<button data-source-mode="Messages" class="${sourceMode==='Messages'?'active':''}">${icon('message')} Messages</button>`}</div>`:''}${source.id==='self'&&sourceMode==='Scheduled'?scheduledPostsView():source.member&&sourceMode==='Messages'?conversationView(source):`<div class="filters">${['All updates','Unread'].map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${list.length?list.map(postView).join(''):'<div class="empty">No updates</div>'}`}`}
const pendingFiles={},mediaUrls=new Map();let recording=null,mediaDatabase;
const formatDuration=n=>`${Math.floor((n||0)/60)}:${String(Math.floor((n||0)%60)).padStart(2,'0')}`;
const fileSize=n=>{if(n<1024)return n+' B';const units=['KB','MB','GB','TB'];let value=n/1024,index=0;while(value>=1024&&index<units.length-1){value/=1024;index++}return value.toFixed(value<10?1:0)+' '+units[index]};
function openMediaDB(){if(!mediaDatabase)mediaDatabase=new Promise((resolve,reject)=>{const r=indexedDB.open('daily-message-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return mediaDatabase}
async function storeMedia(id,blob){const db=await openMediaDB();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function mediaUrl(id){if(mediaUrls.has(id))return mediaUrls.get(id);const db=await openMediaDB();const blob=await new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(!blob)throw Error('Attachment unavailable');const url=URL.createObjectURL(blob);mediaUrls.set(id,url);return url}
function attachmentView(a){if(a.kind==='gif')return `<div class="gif-message"><img src="${esc(a.url)}" alt="${esc(a.name)}" loading="lazy"><span>GIF</span></div>`;if(a.kind==='voice')return `<div class="voice-clip" data-media="${esc(a.id)}"><button type="button" class="voice-play" aria-label="Play voice message">${icon('play')}</button><div class="voice-track"><div class="voice-wave" aria-hidden="true">${Array.from({length:32},(_,i)=>`<i style="height:${Math.max(4,Math.round((a.wave?.[i]||0.1)*26))}px"></i>`).join('')}</div><input class="voice-seek" type="range" min="0" max="${a.duration||1}" step="0.1" value="0" aria-label="Voice message position"></div><span class="voice-time">${formatDuration(a.duration)}</span><audio preload="metadata"></audio></div>`;return `<div class="file-attachment" data-media="${esc(a.id)}">${a.type.startsWith('image/')?'<img class="attached-image" alt="'+esc(a.name)+'" loading="lazy">':icon('file')}<div><a class="file-download" download="${esc(a.name)}">${esc(a.name)}</a><small>${fileSize(a.size)}</small></div>${icon('download')}</div>`}
function reactionView(m){return `<div class="reactions">${Object.entries(m.reactions||{}).filter(([,n])=>n).map(([emoji])=>`<button type="button" class="reaction selected" data-react-message="${m.id}" data-emoji="${esc(emoji)}" aria-label="Remove ${esc(emoji)} reaction" aria-pressed="true">${esc(emoji)} <span>1</span></button>`).join('')}</div>`}
const actorId=new URLSearchParams(location.search).get('participant')==='member-maya'?'member-maya':'self';
const messageAuthor=m=>m.author||'self';
const authorName=id=>id==='self'?profile.name:sources.find(s=>s.id===id)?.name||'Member';
const conversationPartner=s=>actorId==='self'?s.name:profile.name;
let editingMessage=null;const editingDrafts={},revealedMessages=new Set(),typingPeers=new Map();let typingTimer,readObserver;
const messageEvents=typeof BroadcastChannel==='function'?new BroadcastChannel('daily-conversations'):null;
function syncConversations(){try{const data=JSON.parse(localStorage.getItem('daily-mockup')||'{}');conversations=data.conversations||conversations}catch{}}
function announceTyping(active){const sourceId=selectedSource;messageEvents?.postMessage({type:'typing',sourceId,actorId,active});clearTimeout(typingTimer);if(active)typingTimer=setTimeout(()=>messageEvents?.postMessage({type:'typing',sourceId,actorId,active:false}),3500)}
function renderTyping(){const el=document.querySelector('#typing-status');if(!el)return;const active=[...typingPeers.values()].filter(p=>p.sourceId===selectedSource&&p.actorId!==actorId&&p.until>Date.now());el.innerHTML=active.length?`<span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>${esc(authorName(active[0].actorId))} is typing</span>`:''}
if(messageEvents)messageEvents.onmessage=e=>{const m=e.data;if(m?.type!=='typing'||m.actorId===actorId)return;const key=m.sourceId+':'+m.actorId;typingPeers.set(key,{...m,until:m.active?Date.now()+5000:0});renderTyping();setTimeout(renderTyping,5100)};
function messageTime(time,full=true){const options={...(full?{month:'short',day:'numeric'}:{}),hour:'numeric',minute:'2-digit'};if(settings.messagePrecision!=='minutes')options.second='2-digit';if(settings.messagePrecision==='milliseconds')options.fractionalSecondDigits=3;try{options.timeZone=profile.timezone;return new Intl.DateTimeFormat(undefined,options).format(new Date(time))}catch{delete options.timeZone;return new Intl.DateTimeFormat(undefined,options).format(new Date(time))}}
function receiptView(messages){const m=[...messages].reverse().find(m=>messageAuthor(m)===actorId);if(!m)return '';const seen=(m.readBy||[]).find(id=>id!==actorId);return `<div class="read-receipt" data-receipt="${m.id}">${seen?`${icon('check')} Read`:'Sent'}</div>`}
function messageMarkup(messages){messages.forEach((m,i)=>m.id||='legacy-'+i);return (messages.length?messages.map((m,i)=>{const author=messageAuthor(m),own=author===actorId,previous=messages[i-1],grouped=previous&&messageAuthor(previous)===author&&new Date(m.time)-new Date(previous.time)<300000;const show=!m.retractedAt||revealedMessages.has(m.id);const edit=editingMessage===m.id;return `<article class="chat-message ${grouped?'grouped':''}" data-chat-id="${m.id}">${grouped?'<span class="group-gutter"></span>':`<span class="avatar">${esc(authorName(author).slice(0,1))}</span>`}<div class="message-main">${grouped&&settings.messagePrecision!=='minutes'?`<time class="grouped-timestamp" datetime="${m.time}">${esc(messageTime(m.time,false))}</time>`:''}${!grouped?`<header><span class="message-author"><strong>${esc(authorName(author))}</strong>${author==='self'?(settings.showUsername?`<small>@${esc(profile.username)}</small>`:''):`<small>@${esc(sources.find(s=>s.id===author)?.username||'')}</small>`}</span><time datetime="${esc(m.time)}">${esc(messageTime(m.time,false))}</time></header>`:''}${m.retractedAt?`<div class="retracted-label">Message retracted <button type="button" data-reveal-message="${m.id}" aria-expanded="${show}">${show?'Hide message':'View message'}</button></div>`:''}${edit?`<form class="edit-message-form" data-edit-form="${m.id}"><textarea aria-label="Edit message" maxlength="4000" rows="2">${esc(editingDrafts[m.id]??m.text)}</textarea><div><button type="button" data-cancel-edit="${m.id}">Cancel</button><button type="submit" class="btn">Save</button></div></form>`:show?`${m.text?`<p class="${m.retractedAt?'retracted-content':''}">${esc(m.text)}</p>`:''}<div class="message-attachments">${(m.attachments||[]).map(attachmentView).join('')}</div>`:''}${m.editedAt?`<button class="edited-label" type="button" data-edit-history="${m.id}" aria-label="View edit history">edited</button>`:''}${!m.retractedAt?reactionView(m):''}</div><div class="message-tools">${!m.retractedAt?`<button type="button" class="add-reaction" data-reaction-picker="${m.id}" aria-label="Add reaction" title="Add reaction">${icon('smile')}</button>${own?`<button type="button" data-edit-message="${m.id}" aria-label="Edit message" title="Edit">${icon('edit')}</button><button type="button" data-retract-message="${m.id}" aria-label="Retract message" title="Retract">${icon('retract')}</button>`:''}`:''}</div></article>`}).join(''):'<span class="empty">No messages</span>')+receiptView(messages)}
function refreshMessageList(){const history=document.querySelector('.message-history');if(!history)return;const atEnd=history.scrollHeight-history.scrollTop-history.clientHeight<80,y=history.scrollTop;history.innerHTML=messageMarkup(conversations[selectedSource]||[]);bindMessageActions();hydrateMedia(history);history.scrollTop=atEnd?history.scrollHeight:y;observeReadMessages()}
function observeReadMessages(){readObserver?.disconnect();const history=document.querySelector('.message-history');if(!history||document.hidden||!document.hasFocus()||!navigator.onLine)return;readObserver=new IntersectionObserver(entries=>{if(document.hidden||!document.hasFocus()||!navigator.onLine)return;const visible=entries.filter(e=>e.isIntersecting&&e.intersectionRatio>=.6).map(e=>e.target.dataset.chatId);if(!visible.length)return;syncConversations();let changed=false;for(const m of conversations[selectedSource]||[]){if(visible.includes(m.id)&&messageAuthor(m)!==actorId&&!(m.readBy||[]).includes(actorId)){(m.readBy||=[]).push(actorId);changed=true}}if(changed)persist()},{root:history,threshold:.6});history.querySelectorAll('[data-chat-id]').forEach(e=>readObserver.observe(e))}
window.addEventListener('storage',e=>{if(e.key!=='daily-mockup')return;syncConversations();refreshMessageList()});
window.addEventListener('focus',observeReadMessages);document.addEventListener('visibilitychange',()=>{if(document.hidden)announceTyping(false);else observeReadMessages()});window.addEventListener('pagehide',()=>announceTyping(false));
function bindMessageActions(){const find=id=>(conversations[selectedSource]||[]).find(m=>m.id===id);document.querySelectorAll('[data-edit-message]').forEach(b=>b.onclick=()=>{const m=find(b.dataset.editMessage);if(messageAuthor(m)!==actorId||m.retractedAt)return;editingMessage=m.id;editingDrafts[m.id]=m.text;refreshMessageList();document.querySelector('.edit-message-form textarea').focus()});document.querySelectorAll('[data-cancel-edit]').forEach(b=>b.onclick=()=>{delete editingDrafts[b.dataset.cancelEdit];editingMessage=null;refreshMessageList()});document.querySelectorAll('[data-edit-form]').forEach(form=>{const input=form.querySelector('textarea');input.oninput=()=>editingDrafts[form.dataset.editForm]=input.value;input.onkeydown=e=>{if(e.key==='Escape'){editingMessage=null;refreshMessageList()}else if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();form.requestSubmit()}};form.onsubmit=e=>{e.preventDefault();syncConversations();const m=find(form.dataset.editForm),text=input.value.trim();if(!m||messageAuthor(m)!==actorId||m.retractedAt)return;if(!text&&!m.attachments?.length)return;if(text!==m.text){m.revisions||=[{text:m.text,time:m.time}];const time=new Date().toISOString();m.revisions.push({text,time});m.text=text;m.editedAt=time;m.readBy=[actorId];persist()}editingMessage=null;delete editingDrafts[m.id];refreshMessageList()}});document.querySelectorAll('[data-retract-message]').forEach(b=>b.onclick=()=>{syncConversations();const m=find(b.dataset.retractMessage);if(!m||messageAuthor(m)!==actorId)return;m.retractedAt=new Date().toISOString();persist();refreshMessageList()});document.querySelectorAll('[data-reveal-message]').forEach(b=>b.onclick=()=>{const id=b.dataset.revealMessage;revealedMessages.has(id)?revealedMessages.delete(id):revealedMessages.add(id);refreshMessageList()});document.querySelectorAll('[data-edit-history]').forEach(b=>b.onclick=()=>{const m=find(b.dataset.editHistory);modal('Edit history',`<div class="edit-history">${(m.revisions||[]).map((r,i)=>`<article><header><span>${i===0?'Original':i===m.revisions.length-1?'Current':'Revision '+i}</span><time>${esc(messageTime(r.time))}</time></header><p>${esc(r.text)||'No text'}</p></article>`).join('')}</div>`)});document.querySelectorAll('[data-reaction-picker]').forEach(button=>button.onclick=()=>emojiPicker(button,emoji=>{syncConversations();const m=find(button.dataset.reactionPicker);m.reactions||={};m.reactions[emoji]=!m.reactions[emoji];persist();refreshMessageList()}));document.querySelectorAll('[data-react-message]').forEach(button=>button.onclick=()=>{syncConversations();const m=find(button.dataset.reactMessage);m.reactions[button.dataset.emoji]=false;persist();refreshMessageList()})}

function conversationView(source){return `<section class="conversation" aria-label="Conversation with ${esc(conversationPartner(source))}"><div id="call-space">${callStateView()}</div><div class="message-history" role="log" aria-live="polite">${messageMarkup(conversations[source.id]||[])}</div><div id="typing-status" role="status" aria-live="polite"></div><div class="composer-area"><div id="attachment-drafts"></div><div class="recording-controls" id="recording-controls" hidden><span class="record-indicator"></span><span id="record-time">0:00</span><span class="record-wave" aria-hidden="true">▂ ▅ ▃ ▇ ▄ ▂ ▆ ▃</span><button type="button" id="discard-recording" aria-label="Discard recording">${icon('trash')}</button><button type="button" id="stop-recording" class="btn">Stop</button></div><form id="message-form"><button type="button" id="attach-files" class="composer-icon" aria-label="Attach files" title="Attach files">${icon('plus')}</button><input type="file" id="file-input" multiple hidden><textarea id="message-input" aria-label="Message ${esc(conversationPartner(source))}" placeholder="Message ${esc(conversationPartner(source))}" rows="1" maxlength="4000">${esc(messageDrafts[source.id]||'')}</textarea><button type="button" id="compose-emoji" class="composer-icon" aria-label="Add emoji" title="Add emoji">${icon('smile')}</button><button type="button" id="compose-gif" class="composer-icon gif-button" aria-label="Send GIF" title="GIF">GIF</button><button type="button" id="record-voice" class="composer-icon" aria-label="Record voice message" title="Click to record, or hold and release to send">${icon('mic')}</button><button type="submit" class="composer-icon send-message" aria-label="Send message">${icon('send')}</button></form></div></section>`}
function drawPending(){const holder=document.querySelector('#attachment-drafts');if(!holder)return;const list=pendingFiles[selectedSource]||[];holder.innerHTML=list.map((a,i)=>`<div class="pending-attachment">${attachmentView(a)}<button type="button" data-remove-file="${i}" aria-label="Remove ${esc(a.name)}">${icon('close')}</button></div>`).join('');holder.querySelectorAll('[data-remove-file]').forEach(e=>e.onclick=()=>{pendingFiles[selectedSource].splice(+e.dataset.removeFile,1);drawPending()});hydrateMedia(holder);updateSend()}
function updateSend(){const button=document.querySelector('.send-message');if(button)button.disabled=!document.querySelector('#message-input').value.trim()&&!(pendingFiles[selectedSource]||[]).length}
async function addFiles(files,sourceId){for(const f of files){try{const a={id:crypto.randomUUID(),name:f.name,type:f.type||'application/octet-stream',size:f.size,kind:'file'};await storeMedia(a.id,f);(pendingFiles[sourceId]||= []).push(a)}catch(e){toast(e.name==='QuotaExceededError'?'Device storage is full. Attachment not added.':'Could not save attachment')}}if(sourceId===selectedSource)drawPending()}
async function hydrateMedia(root=document){for(const el of root.querySelectorAll('[data-media]')){try{const url=await mediaUrl(el.dataset.media);if(!el.isConnected)continue;if(el.classList.contains('voice-clip')){const audio=el.querySelector('audio'),button=el.querySelector('.voice-play'),seek=el.querySelector('.voice-seek'),time=el.querySelector('.voice-time');audio.src=url;audio.muted=mediaControls.deafened;button.onclick=async()=>{try{if(audio.paused){document.querySelectorAll('audio').forEach(other=>{if(other!==audio)other.pause()});await audio.play()}else audio.pause()}catch{toast('Audio playback unavailable')}};audio.onplay=()=>{button.innerHTML=icon('pause');button.setAttribute('aria-label','Pause voice message')};audio.onpause=audio.onended=()=>{button.innerHTML=icon('play');button.setAttribute('aria-label','Play voice message')};audio.onloadedmetadata=()=>{if(Number.isFinite(audio.duration)&&audio.duration>0)seek.max=audio.duration};audio.ontimeupdate=()=>{seek.value=audio.currentTime;time.textContent=formatDuration(audio.currentTime);el.style.setProperty('--played',Math.min(100,100*audio.currentTime/Number(seek.max))+'%')};seek.oninput=()=>{audio.currentTime=Number(seek.value)};audio.onerror=()=>{button.disabled=true;time.textContent='Unavailable'}}else{const a=el.querySelector('a');a.href=url;const img=el.querySelector('img');if(img)img.src=url}}catch{el.classList.add('media-missing');el.title='Attachment unavailable on this device'}}}
function emojiPicker(anchor,onChoose){document.querySelector('.emoji-picker')?.remove();const picker=document.createElement('div');picker.className='emoji-picker';picker.setAttribute('role','dialog');picker.setAttribute('aria-label','Choose emoji');picker.innerHTML=['👍','❤️','😂','🙌','👀','🔥','✨','🎉','🤔','💀','😭','✅'].map(e=>`<button type="button" aria-label="${e}">${e}</button>`).join('')+'<button type="button" class="emoji-close" aria-label="Close emoji picker">×</button>';document.body.append(picker);const r=anchor.getBoundingClientRect();picker.style.left=Math.max(12,Math.min(innerWidth-248,r.left-100))+'px';picker.style.top=Math.max(12,Math.min(innerHeight-170,r.top-160))+'px';picker.querySelectorAll('button').forEach(button=>button.onclick=()=>{if(!button.classList.contains('emoji-close'))onChoose(button.textContent);picker.remove();anchor.isConnected&&anchor.focus()});picker.onkeydown=e=>{if(e.key==='Escape'){picker.remove();anchor.focus()}};const outside=e=>{if(!picker.contains(e.target)&&e.target!==anchor){picker.remove();document.removeEventListener('pointerdown',outside)}};setTimeout(()=>document.addEventListener('pointerdown',outside),0);picker.querySelector('button').focus()}
function cancelRecording(){if(!recording)return;recording.discard=true;if(recording.recorder?.state==='recording')recording.recorder.stop();recording.stream?.getTracks().forEach(t=>t.stop());clearInterval(recording.timer);recording=null}
async function voicePeaks(blob){try{const context=new OfflineAudioContext(1,1,22050),buffer=await context.decodeAudioData(await blob.arrayBuffer()),data=buffer.getChannelData(0),step=Math.max(1,Math.floor(data.length/32));const peaks=Array.from({length:32},(_,i)=>{let peak=0;for(let n=i*step;n<Math.min((i+1)*step,data.length);n++)peak=Math.max(peak,Math.abs(data[n]));return peak});const max=Math.max(.01,...peaks);return {wave:peaks.map(n=>n/max),duration:buffer.duration}}catch{return {}}}
async function startRecording(){if(mediaControls.muted){toast('Unmute to record a voice message');return}if(recording)return;const state={sourceId:selectedSource,started:performance.now(),chunks:[],discard:false};recording=state;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('unsupported');state.stream=await navigator.mediaDevices.getUserMedia({audio:true});if(recording!==state){state.stream.getTracks().forEach(t=>t.stop());return}const type=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));state.recorder=new MediaRecorder(state.stream,type?{mimeType:type}:undefined);state.recorder.ondataavailable=e=>{if(e.data.size)state.chunks.push(e.data)};state.recorder.onstop=async()=>{state.stream.getTracks().forEach(t=>t.stop());clearInterval(state.timer);if(recording===state)recording=null;document.querySelector('#recording-controls')?.setAttribute('hidden','');document.querySelector('#record-voice')?.setAttribute('aria-pressed','false');if(state.discard)return;try{const blob=new Blob(state.chunks,{type:state.recorder.mimeType});if(!blob.size)return;const a={id:crypto.randomUUID(),kind:'voice',name:'Voice message',type:blob.type,size:blob.size,duration:(performance.now()-state.started)/1000};Object.assign(a,await voicePeaks(blob));await storeMedia(a.id,blob);(pendingFiles[state.sourceId]||=[]).push(a);if(state.sourceId===selectedSource&&document.querySelector('#message-form')){drawPending();if(state.sendOnStop)sendMessage()}}catch{toast('Could not save recording')}};state.started=performance.now();state.recorder.start();document.querySelector('#recording-controls').hidden=false;document.querySelector('#record-voice').setAttribute('aria-pressed','true');state.timer=setInterval(()=>{const time=document.querySelector('#record-time');if(time)time.textContent=formatDuration((performance.now()-state.started)/1000);},250);if(state.releaseRequested)stopRecording(state.sendOnStop)}catch(e){state.stream?.getTracks().forEach(t=>t.stop());if(recording===state)recording=null;toast(e.name==='NotAllowedError'?'Microphone permission is required':e.name==='NotFoundError'?'No microphone found':'Voice recording unavailable')}}
function stopRecording(send){if(!recording)return;recording.sendOnStop=send;if(recording.recorder?.state==='recording')recording.recorder.stop();else recording.releaseRequested=true}
function sendMessage(){const input=document.querySelector('#message-input');if(!input||recording)return;const text=input.value.trim(),attachments=pendingFiles[selectedSource]||[];if(!text&&!attachments.length)return;syncConversations();announceTyping(false);(conversations[selectedSource]||=[]).push({id:crypto.randomUUID(),text,time:new Date().toISOString(),attachments,reactions:{},author:actorId,readBy:[actorId]});messageDrafts[selectedSource]='';pendingFiles[selectedSource]=[];persist();render();document.querySelector('#message-input')?.focus();const history=document.querySelector('.message-history');history.scrollTop=history.scrollHeight}
function bindMessaging(){document.querySelectorAll('[data-message-source]').forEach(e=>e.onclick=()=>{selectedSource=e.dataset.messageSource;go('Source');sourceMode='Messages';render();document.querySelector('#message-input').focus()});document.querySelectorAll('[data-source-mode]').forEach(e=>e.onclick=()=>{cancelRecording();sourceMode=e.dataset.sourceMode;render()});const input=document.querySelector('#message-input'),form=document.querySelector('#message-form');if(!form)return;document.querySelector('#attach-files').onclick=()=>document.querySelector('#file-input').click();document.querySelector('#file-input').onchange=e=>{addFiles([...e.target.files],selectedSource);e.target.value=''};input.oninput=()=>{messageDrafts[selectedSource]=input.value;announceTyping(!!input.value.trim());input.style.height='auto';input.style.height=Math.min(input.scrollHeight,180)+'px';updateSend()};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}};form.onsubmit=e=>{e.preventDefault();sendMessage()};document.querySelector('#compose-emoji').onclick=e=>emojiPicker(e.currentTarget,emoji=>{const start=input.selectionStart,end=input.selectionEnd;input.setRangeText(emoji,start,end,'end');input.dispatchEvent(new Event('input'));input.focus()});document.querySelector('#compose-gif').onclick=gifPicker;const mic=document.querySelector('#record-voice');let pressedAt=0;mic.onpointerdown=e=>{if(e.button!==0||recording)return;pressedAt=performance.now();mic.setPointerCapture(e.pointerId);startRecording()};mic.onpointerup=()=>{if(performance.now()-pressedAt>350&&recording)stopRecording(true)};mic.onpointercancel=cancelRecording;mic.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();recording?stopRecording(false):startRecording()}};document.querySelector('#discard-recording').onclick=()=>{cancelRecording();document.querySelector('#recording-controls').hidden=true;mic.setAttribute('aria-pressed','false')};document.querySelector('#stop-recording').onclick=()=>stopRecording(false);bindMessageActions();renderTyping();observeReadMessages();form.ondragover=e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();form.classList.add('dragging')}};form.ondragleave=()=>form.classList.remove('dragging');form.ondrop=e=>{e.preventDefault();form.classList.remove('dragging');addFiles([...e.dataTransfer.files],selectedSource)};drawPending();hydrateMedia(document.querySelector('.message-history'))}

function bindSourceOpen(){document.querySelectorAll('[data-open-source]').forEach(b=>b.onclick=()=>{selectedSource=b.dataset.openSource;go('Source')})}
function bindUpdates(){document.querySelectorAll('[data-post]').forEach(d=>d.ontoggle=()=>{const target=d.querySelector('.update-content');if(!d.open){target.innerHTML='';return}const p=posts.find(p=>p.id===+d.dataset.post);target.innerHTML=expandedPost(p);bindPublicationView(target);target.querySelector('[data-read]').onclick=()=>{read=read.includes(p.id)?read.filter(n=>n!==p.id):[...read,p.id];persist();const y=window.scrollY;render();const reopened=document.querySelector(`[data-post="${p.id}"]`);if(reopened)reopened.open=true;window.scrollTo(0,y)};target.querySelector('[data-save]').onclick=e=>{const exists=saved.includes(p.id);saved=exists?saved.filter(n=>n!==p.id):[...saved,p.id];persist();e.currentTarget.style.color=exists?'':'#fff';e.currentTarget.setAttribute('aria-label',exists?'Save update':'Unsave update');toast(exists?'Removed from saved':'Saved')}})}
function settingsView(){return `<div class="page-title"><h1>Settings</h1></div><div class="settings-panel"><section><h2>Profile</h2><label class="setting-row"><span>Show my username</span><input type="checkbox" id="show-username" ${settings.showUsername?'checked':''} role="switch"></label></section><section><h2>Messages</h2><label class="setting-row"><span>Timestamp precision</span><select id="message-precision">${[['minutes','Minutes'],['seconds','Seconds'],['milliseconds','Milliseconds']].map(([v,l])=>`<option value="${v}" ${settings.messagePrecision===v?'selected':''}>${l}</option>`).join('')}</select></label><time class="timestamp-preview">${esc(messageTime(new Date().toISOString()))}</time></section></div>`}
function bindSettingsAndPost(){document.querySelector('#new-post').onclick=postComposer;const name=document.querySelector('#show-username');if(name)name.onchange=()=>{settings.showUsername=name.checked;persist();render();document.querySelector('#show-username').focus()};const precision=document.querySelector('#message-precision');if(precision)precision.onchange=()=>{settings.messagePrecision=precision.value;persist();render();document.querySelector('#message-precision').focus()}}
const gifCollection=[{name:'Hello',url:'assets/hello.gif',tags:'hello hi wave greeting'},{name:'Celebrate',url:'assets/celebrate.gif',tags:'celebrate party yes cheers'},{name:'Thanks',url:'assets/thanks.gif',tags:'thanks thank you heart love'},{name:'Loading',url:'assets/loading.gif',tags:'loading wait thinking'}];
function gifPicker(){modal('GIFs',`<form id="gif-search" class="gif-search"><input type="text" id="gif-query" placeholder="Search GIFs" aria-label="Search GIFs"><button class="btn" aria-label="Search GIFs">${icon('search')}</button></form><div id="gif-results" class="gif-grid"></div>`);const show=()=>{const query=document.querySelector('#gif-query').value.trim().toLowerCase(),list=gifCollection.filter(g=>!query||g.tags.includes(query)||g.name.toLowerCase().includes(query));document.querySelector('#gif-results').innerHTML=list.map(g=>`<button type="button" data-gif="${gifCollection.indexOf(g)}" aria-label="Send ${esc(g.name)} GIF"><img src="${g.url}" alt="${g.name}"><span>${g.name}</span></button>`).join('')||'<div class="empty">No GIFs</div>';document.querySelectorAll('[data-gif]').forEach(b=>b.onclick=()=>{const g=gifCollection[+b.dataset.gif];(pendingFiles[selectedSource]||=[]).push({id:crypto.randomUUID(),kind:'gif',name:g.name,url:g.url});document.querySelector('#modal').close();drawPending();sendMessage()})};document.querySelector('#gif-search').onsubmit=e=>{e.preventDefault();show()};show();document.querySelector('#gif-query').focus()}

const availabilityChoices=[['chat','Chat'],['calls','Calls'],['both','Chat & calls'],['unavailable','Not available']];
function bindAvailability(){const toggle=document.querySelector('#availability-toggle'),menu=document.querySelector('#availability-menu');if(!toggle||!menu)return;const close=()=>{menu.hidden=true;toggle.setAttribute('aria-expanded','false')};toggle.onclick=()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)menu.querySelector('[aria-checked="true"]').focus()};menu.querySelectorAll('[data-availability]').forEach(button=>button.onclick=()=>{profile.openTo=button.dataset.availability;persist();render();document.querySelector('#availability-toggle').focus()});menu.onkeydown=e=>{const buttons=[...menu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close();toggle.focus()}else if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus()}};toggle.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();menu.hidden=false;toggle.setAttribute('aria-expanded','true');menu.querySelector('button').focus()}}}
document.addEventListener('pointerdown',e=>{const menu=document.querySelector('#availability-menu'),toggle=document.querySelector('#availability-toggle');if(menu&&!menu.contains(e.target)&&!toggle?.contains(e.target)){menu.hidden=true;toggle?.setAttribute('aria-expanded','false')}});
icons.clock='<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>';
icons.phone='<path d="m7 3 3 5-3 3q2 4 6 6l3-3 5 3-1 4C10 23 1 14 3 4Z"/>';
const callChannel=typeof BroadcastChannel==='function'?new BroadcastChannel('daily-calls'):null;
let activeCall=null;const incomingCalls=new Map();let callFrame;
function callSignal(type,data={}){callChannel?.postMessage({type,actorId,callId:activeCall?.id,sourceId:activeCall?.sourceId,...data})}
function callStateView(){const invite=incomingCalls.get(selectedSource),call=activeCall?.sourceId===selectedSource?activeCall:null;if(!call&&!invite)return '';if(!call)return `<div class="call-invite"><span>${esc(authorName(invite.actorId))} wants to call</span><div><button class="btn" id="decline-call">Decline</button><button class="btn" id="join-preview">Preview</button></div></div>`;return `<div class="call-panel"><div class="call-panel-head"><span>${call.phase==='live'?'In call':call.phase==='connecting'?'Connecting':'Call preview'}</span><button id="leave-call" aria-label="${call.phase==='live'?'End call':'Cancel call'}">${icon('close')}</button></div><div class="call-preview-people"><div><span class="call-avatar">${esc(authorName(actorId).slice(0,1))}</span><span>You</span><small>${call.localReady?'Ready':'Not ready'}</small></div><div><span class="call-avatar">${esc(authorName(actorId==='self'?'member-maya':'self').slice(0,1))}</span><span>${esc(authorName(actorId==='self'?'member-maya':'self'))}</span><small>${call.remoteReady?'Ready':'Not ready'}</small></div></div><canvas id="call-visualizer" aria-label="Microphone level preview" role="img" width="640" height="60"></canvas><div class="call-panel-footer"><span role="status">${esc(call.error|| (call.loading?'Requesting microphone':call.phase==='live'?'Connected':call.phase==='connecting'?'Connecting audio':call.localReady?'Waiting for the other person':'Check your microphone'))}</span>${call.phase==='preview'?`<button class="btn ${call.localReady?'':'primary'}" id="ready-call" ${!call.stream||call.loading?'disabled':''}>${call.localReady?'Not ready':'Ready'}</button>`:`<button class="btn" id="end-call">End call</button>`}${!call.stream&&!call.loading?'<button class="btn" id="retry-mic">Enable microphone</button>':''}</div></div>`}
function updateCallUI(){const root=document.querySelector('#call-space');if(root){root.innerHTML=callStateView();bindCallPanel()}updateCallReturn()}
function updateCallReturn(){let root=document.querySelector('#active-call-return');if(!root){root=document.createElement('div');root.id='active-call-return';document.querySelector('.sidebar-bottom')?.prepend(root)}if(!root)return;root.innerHTML=activeCall?`<button id="return-call">${icon('phone')} ${activeCall.phase==='live'?'Call in progress':'Call preview'}</button><button id="quick-end-call" aria-label="End call">${icon('close')}</button>`:'';root.querySelector('#return-call')?.addEventListener('click',()=>{selectedSource=activeCall.sourceId;go('Source');sourceMode='Messages';render()});root.querySelector('#quick-end-call')?.addEventListener('click',()=>endCall(true))}
function bindCalls(){document.querySelector('#start-call')?.addEventListener('click',()=>{if(activeCall){selectedSource=activeCall.sourceId;go('Source');sourceMode='Messages';render();return}beginCall()});bindCallPanel();updateCallReturn();callSignal('hello')}
function bindCallPanel(){cancelAnimationFrame(callFrame);document.querySelector('#ready-call')?.addEventListener('click',()=>{const c=activeCall;if(!c?.stream||c.phase!=='preview')return;c.localReady=!c.localReady;callSignal('ready',{ready:c.localReady});updateCallUI();maybeConnect()});document.querySelector('#retry-mic')?.addEventListener('click',prepareCallMic);document.querySelector('#leave-call')?.addEventListener('click',()=>endCall(true));document.querySelector('#end-call')?.addEventListener('click',()=>endCall(true));document.querySelector('#join-preview')?.addEventListener('click',()=>beginCall(incomingCalls.get(selectedSource)));document.querySelector('#decline-call')?.addEventListener('click',()=>{const invite=incomingCalls.get(selectedSource);callSignal('end',{callId:invite.callId,sourceId:selectedSource});incomingCalls.delete(selectedSource);updateCallUI()});drawCallVisualizer()}
async function beginCall(invite){if(activeCall)return;if(!callChannel||!window.RTCPeerConnection){toast('Calls unavailable in this browser');return}activeCall={id:invite?.callId||crypto.randomUUID(),sourceId:selectedSource,caller:!invite,localReady:false,remoteReady:invite?.remoteReady||false,phase:'preview',stream:null,context:null,pc:null,candidates:[],loading:false};incomingCalls.delete(selectedSource);sourceMode='Messages';render();if(!invite)callSignal('invite');else callSignal('joined');await prepareCallMic()}
async function prepareCallMic(){const c=activeCall;if(!c||c.loading||c.stream)return;c.loading=true;c.error='';updateCallUI();try{if(!navigator.mediaDevices?.getUserMedia)throw Error('unsupported');const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(activeCall!==c){stream.getTracks().forEach(t=>t.stop());return}c.stream=stream;stream.getAudioTracks().forEach(t=>t.enabled=!mediaControls.muted);c.context=new AudioContext();await c.context.resume();c.analyser=c.context.createAnalyser();c.analyser.fftSize=256;c.context.createMediaStreamSource(stream).connect(c.analyser);stream.getAudioTracks()[0].onended=()=>{if(activeCall===c)endCall(true,'Microphone disconnected')}}catch(e){c.error=e.name==='NotAllowedError'?'Allow microphone access to get ready':e.name==='NotFoundError'?'No microphone found':'Microphone unavailable'}finally{if(activeCall===c){c.loading=false;updateCallUI()}}}
function drawCallVisualizer(){const canvas=document.querySelector('#call-visualizer'),c=activeCall;if(!canvas)return;const ctx=canvas.getContext('2d'),data=new Uint8Array(c?.analyser?.frequencyBinCount||128);const draw=()=>{if(!canvas.isConnected||activeCall!==c)return;ctx.clearRect(0,0,canvas.width,canvas.height);if(c?.analyser)c.analyser.getByteFrequencyData(data);ctx.fillStyle='#aaa';for(let i=0;i<48;i++){const value=data[Math.floor(i*data.length/48)]||0,height=Math.max(3,value/255*48);ctx.fillRect(i*13+4,(60-height)/2,5,height)}callFrame=requestAnimationFrame(draw)};draw()}
async function makeCallPeer(c){if(c.pc)return c.pc;const pc=new RTCPeerConnection({iceServers:[]});c.pc=pc;c.connectTimer=setTimeout(()=>{if(activeCall===c&&c.phase!=='live')endCall(true,'Audio connection unavailable')},15000);c.stream.getTracks().forEach(t=>pc.addTrack(t,c.stream));pc.onicecandidate=e=>{if(e.candidate&&activeCall===c)callSignal('ice',{candidate:e.candidate.toJSON()})};pc.ontrack=e=>{if(activeCall!==c)return;const audio=document.createElement('audio');audio.id='call-remote-audio';audio.autoplay=true;audio.muted=mediaControls.deafened;audio.srcObject=e.streams[0];document.body.append(audio);c.audio=audio;audio.play().catch(()=>{c.error='Click Resume audio';updateCallUI();const root=document.querySelector('.call-panel-footer');if(root){const button=document.createElement('button');button.className='btn';button.textContent='Resume audio';button.onclick=()=>audio.play().then(()=>{c.error='';updateCallUI()});root.append(button)}})};pc.onconnectionstatechange=()=>{if(activeCall!==c)return;if(pc.connectionState==='connected'){c.phase='live';clearTimeout(c.connectTimer);c.error='';updateCallUI()}else if(pc.connectionState==='failed'||pc.connectionState==='closed')endCall(true,'Call disconnected')};return pc}
async function maybeConnect(){const c=activeCall;if(!c?.caller||!c.localReady||!c.remoteReady||c.phase!=='preview')return;c.phase='connecting';updateCallUI();try{const pc=await makeCallPeer(c);await pc.setLocalDescription(await pc.createOffer());if(activeCall===c)callSignal('offer',{description:pc.localDescription.toJSON()})}catch{endCall(true,'Could not connect call')}}
async function flushCandidates(c){for(const candidate of c.candidates.splice(0))await c.pc.addIceCandidate(candidate)}
if(callChannel)callChannel.onmessage=async e=>{const m=e.data;if(!m||m.actorId===actorId)return;try{if(m.type==='hello'){if(activeCall?.caller)callSignal('invite');return}if(m.type==='invite'){if(activeCall){if(activeCall.id!==m.callId)callSignal('busy',{callId:m.callId,sourceId:m.sourceId});return}incomingCalls.set(m.sourceId,m);updateCallUI();return}if(m.type==='end'||m.type==='busy'){if(activeCall?.id===m.callId)endCall(false,m.type==='busy'?'The other person is in a call':'Call ended');else{incomingCalls.delete(m.sourceId);updateCallUI()}return}const c=activeCall;if(!c||c.id!==m.callId){if(m.type==='ready'&&incomingCalls.has(m.sourceId))incomingCalls.get(m.sourceId).remoteReady=m.ready;return}if(m.type==='joined'){callSignal('ready',{ready:c.localReady});return}if(m.type==='ready'){c.remoteReady=!!m.ready;updateCallUI();await maybeConnect()}else if(m.type==='offer'&&!c.caller&&c.localReady&&c.remoteReady){c.phase='connecting';updateCallUI();const pc=await makeCallPeer(c);await pc.setRemoteDescription(m.description);await flushCandidates(c);await pc.setLocalDescription(await pc.createAnswer());callSignal('answer',{description:pc.localDescription.toJSON()})}else if(m.type==='answer'&&c.caller&&c.pc){await c.pc.setRemoteDescription(m.description);await flushCandidates(c)}else if(m.type==='ice'){if(c.pc?.remoteDescription)await c.pc.addIceCandidate(m.candidate);else c.candidates.push(m.candidate)}}catch{endCall(true,'Could not connect call')}};
function endCall(notify=false,reason=''){const c=activeCall;if(!c)return;if(notify)callSignal('end');activeCall=null;clearTimeout(c.connectTimer);cancelAnimationFrame(callFrame);c.pc?.close();c.stream?.getTracks().forEach(t=>{t.onended=null;t.stop()});c.context?.close().catch(()=>{});c.audio?.remove();updateCallUI();if(reason)toast(reason)}
window.addEventListener('pagehide',()=>endCall(true));window.addEventListener('offline',()=>endCall(true,'Call disconnected'));

function sourceRow(s){return `<article class="source-card" draggable="${page==='Sources'}" data-draggable-source="${esc(s.id)}"><button class="source-open" data-open-source="${esc(s.id)}"><span class="source-tile">${esc(s.initial)}</span><span class="source-row-name">${esc(s.name)}</span></button>${s.member&&s.id!=='self'?`<button class="message-source" data-message-source="${esc(s.id)}" aria-label="Message ${esc(s.name)}">${icon('message')}<span>Message</span></button>`:''}${!s.saved?`<button class="btn" data-follow="${esc(s.id)}">${icon('plus')} Add</button>`:''}${page==='Sources'&&categories.length?`<button class="move-source" data-move-source="${esc(s.id)}" aria-label="Move ${esc(s.name)} to category" title="Move to category">${icon('folder')}</button>`:''}</article>`}
function categoryDescendants(id){const result=new Set(),stack=[id];while(stack.length){const current=stack.pop();if(result.has(current))continue;result.add(current);for(const c of categories)if(c.parentId===current)stack.push(c.id)}return result}
function categoryPath(c){const names=[],seen=new Set();while(c&&!seen.has(c.id)){seen.add(c.id);names.unshift(c.name);c=categories.find(p=>p.id===c.parentId)}return names.join(' / ')}
function categoryOptions(exclude=null){const blocked=exclude?categoryDescendants(exclude):new Set();return categories.filter(c=>!blocked.has(c.id)).map(c=>`<option value="${c.id}">${esc(categoryPath(c))}</option>`).join('')}
function categoryTree(list){if(!categories.length)return `<div class="source-grid">${list.map(sourceRow).join('')}</div>${!list.length?'<div class="empty">No sources</div>':''}`;const valid=new Set(categories.map(c=>c.id)),children=new Map(),byCategory=new Map();for(const c of categories){const parent=valid.has(c.parentId)?c.parentId:null;if(!children.has(parent))children.set(parent,[]);children.get(parent).push(c)}for(const s of list){const key=valid.has(s.categoryId)?s.categoryId:null;if(!byCategory.has(key))byCategory.set(key,[]);byCategory.get(key).push(s)}let html='<div class="source-categories">';const stack=(children.get(null)||[]).slice().reverse().map(c=>({c,depth:0})),seen=new Set();while(stack.length){const {c,depth}=stack.pop();if(seen.has(c.id))continue;seen.add(c.id);html+=`<section class="source-category" style="--category-depth:${Math.min(depth,4)}"><div class="category-heading" data-drop-category="${c.id}"><button class="category-collapse" data-collapse-category="${c.id}" aria-expanded="${!c.collapsed}" aria-label="${c.collapsed?'Expand':'Collapse'} ${esc(c.name)}"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${c.collapsed?'m9 6 6 6-6 6':'m6 9 6 6 6-6'}"/></svg><span>${esc(c.name)}</span></button><div class="category-actions"><button data-add-child="${c.id}" aria-label="Add subcategory to ${esc(c.name)}" title="Add subcategory">${icon('plus')}</button><button data-edit-category="${c.id}" aria-label="Edit ${esc(c.name)} category" title="Edit category">${icon('more')}</button></div></div>${!c.collapsed?`<div class="source-grid category-sources">${(byCategory.get(c.id)||[]).map(sourceRow).join('')}</div>`:''}</section>`;if(!c.collapsed)for(const child of (children.get(c.id)||[]).slice().reverse())stack.push({c:child,depth:depth+1})}const uncategorized=byCategory.get(null)||[];html+=`<section class="uncategorized-sources"><div class="category-heading" data-drop-category=""><span>Uncategorized</span></div><div class="source-grid">${uncategorized.map(sourceRow).join('')}</div></section></div>`;return html}
function categoryEditor(id=null,parentId=null){const category=categories.find(c=>c.id===id);modal(category?'Edit category':'Create category',`<form id="category-form"><label class="category-field">Name<input type="text" id="category-name" required value="${esc(category?.name||'')}" autocomplete="off"></label><label class="category-field">Parent category<select id="category-parent"><option value="">None</option>${categoryOptions(id)}</select></label><div class="category-form-actions">${category?'<button type="button" id="delete-category">Delete category</button>':''}<button type="submit" class="btn">${category?'Save':'Create'}</button></div></form>`);document.querySelector('#category-parent').value=category?.parentId||parentId||'';document.querySelector('#category-name').focus();document.querySelector('#category-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#category-name').value.trim(),parent=document.querySelector('#category-parent').value||null;if(!name)return;if(id&&categoryDescendants(id).has(parent))return toast('A category cannot contain itself');if(category){category.name=name;category.parentId=parent}else categories.push({id:crypto.randomUUID(),name,parentId:parent,collapsed:false});if(parent){const p=categories.find(c=>c.id===parent);if(p)p.collapsed=false}persist();document.querySelector('#modal').close();render()};document.querySelector('#delete-category')?.addEventListener('click',()=>{for(const s of sources)if(s.categoryId===id)s.categoryId=category.parentId;for(const c of categories)if(c.parentId===id)c.parentId=category.parentId;categories=categories.filter(c=>c.id!==id);persist();document.querySelector('#modal').close();render()})}
function moveSource(id){const s=sources.find(s=>s.id===id);modal('Move '+esc(s.name),`<form id="move-source-form"><label class="category-field">Category<select id="source-category"><option value="">Uncategorized</option>${categoryOptions()}</select></label><button class="btn full" type="submit">Move</button></form>`);document.querySelector('#source-category').value=s.categoryId||'';document.querySelector('#move-source-form').onsubmit=e=>{e.preventDefault();s.categoryId=document.querySelector('#source-category').value||null;persist();document.querySelector('#modal').close();render()}}
function bindCategories(){document.querySelector('#add-category')?.addEventListener('click',()=>categoryEditor());document.querySelectorAll('[data-add-child]').forEach(b=>b.onclick=()=>categoryEditor(null,b.dataset.addChild));document.querySelectorAll('[data-edit-category]').forEach(b=>b.onclick=()=>categoryEditor(b.dataset.editCategory));document.querySelectorAll('[data-collapse-category]').forEach(b=>b.onclick=()=>{const c=categories.find(c=>c.id===b.dataset.collapseCategory);c.collapsed=!c.collapsed;persist();render();document.querySelector(`[data-collapse-category="${c.id}"]`)?.focus()});document.querySelectorAll('[data-move-source]').forEach(b=>b.onclick=()=>moveSource(b.dataset.moveSource));document.querySelectorAll('[data-draggable-source]').forEach(row=>row.ondragstart=e=>{e.dataTransfer.setData('application/x-source-id',row.dataset.draggableSource);e.dataTransfer.effectAllowed='move'});document.querySelectorAll('[data-drop-category]').forEach(target=>{target.ondragover=e=>{if(e.dataTransfer.types.includes('application/x-source-id')){e.preventDefault();target.classList.add('category-drop-target')}};target.ondragleave=()=>target.classList.remove('category-drop-target');target.ondrop=e=>{e.preventDefault();const s=sources.find(s=>s.id===e.dataTransfer.getData('application/x-source-id'));if(s){s.categoryId=target.dataset.dropCategory||null;persist();render()}target.classList.remove('category-drop-target')}})}

let publishingDraft={type:'post',text:typeof postDraft==='string'?postDraft:'',title:'',description:'',attachments:[],question:'',options:['',''],schedule:'',openSource:false,license:'',...stored.publishingDraft},uploadingPostFiles=0,streamPreview=null;
function savePublishingDraft(){postDraft=publishingDraft.text;persist()}
function stopStreamPreview(){streamPreview?.getTracks().forEach(t=>t.stop());streamPreview=null;const video=document.querySelector('#stream-preview');if(video){video.srcObject=null;video.hidden=true}const b=document.querySelector('#preview-stream');if(b)b.textContent='Preview'}
function scheduleISO(value){if(!value)return null;const parts=value.split(/[-T:]/).map(Number),[y,m,d,h,min]=parts;const wanted=Date.UTC(y,m-1,d,h,min);let guess=wanted;const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:profile.timezone||'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});for(let i=0;i<3;i++){const p=Object.fromEntries(formatter.formatToParts(new Date(guess)).map(p=>[p.type,p.value]));const actual=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);guess+=wanted-actual}const check=Object.fromEntries(formatter.formatToParts(new Date(guess)).map(p=>[p.type,p.value]));if(+check.year!==y||+check.month!==m||+check.day!==d||+check.hour!==h||+check.minute!==min)throw Error('This time does not exist in your timezone');return new Date(guess).toISOString()}
function ensureOwnSource(){let s=sources.find(s=>s.id==='self');if(!s){s={id:'self',name:profile.name,initial:profile.name.slice(0,1),color:'#ddd',type:'Person',bio:'',links:['App'],saved:true,member:true,username:profile.username};sources.push(s)}s.name=profile.name;s.username=profile.username;return s}
function postComposer(){stopStreamPreview();const d=publishingDraft;modal('Post',`<form id="post-form" class="publishing-form"><div class="post-author"><span class="avatar">${esc(profile.name.slice(0,1))}</span><span>${esc(profile.name)}${settings.showUsername?`<small>@${esc(profile.username)}</small>`:''}</span></div><div class="publish-types" role="tablist" aria-label="Post type">${[['post','Post'],['poll','Poll'],['live','Live']].map(([v,l])=>`<button type="button" role="tab" aria-selected="${d.type===v}" data-publish-type="${v}">${l}</button>`).join('')}</div>${d.type==='live'?`<div class="stream-setup"><select id="stream-source" aria-label="Stream source"><option value="camera">Camera</option><option value="screen">Screen</option></select><button type="button" class="btn" id="preview-stream">Preview</button><video id="stream-preview" autoplay playsinline muted hidden></video><p class="publish-note">Streaming service not connected</p></div>`:d.type==='poll'?`<div class="poll-editor"><input type="text" id="poll-question" aria-label="Poll question" placeholder="Question" value="${esc(d.question)}"><div id="poll-options">${pollOptionInputs()}</div><button type="button" class="text-action" id="add-poll-option">${icon('plus')} Add option</button></div>`:''}<textarea id="post-content" aria-label="Post content" placeholder="${d.type==='post'?'Write a post':d.type==='poll'?'Add context (optional)':'Stream announcement (optional)'}" rows="${d.type==='post'?4:2}">${esc(d.text)}</textarea><div id="post-attachment-list"></div><div class="publish-tools"><button type="button" id="post-attach" class="btn">${icon('plus')} Files</button><input type="file" id="post-file-input" multiple hidden><button type="button" id="post-schedule-toggle" class="btn" aria-expanded="${!!d.schedule}" aria-controls="post-schedule-panel">${icon('clock')} Schedule</button></div><div id="post-schedule-panel" ${d.schedule?'':'hidden'}><label>Publish time · ${esc(profile.timezone)}<input type="datetime-local" id="post-schedule" aria-label="Publish time" value="${esc(d.schedule)}"></label><button type="button" class="text-action" id="clear-schedule">Clear</button><span class="publish-note">Publishes while this app is open</span></div>${openSourceComposer()}<details class="post-optional" ${d.title||d.description?'open':''}><summary>Title & description <span>optional</span></summary><input type="text" id="post-title" aria-label="Post title (optional)" placeholder="Title" value="${esc(d.title)}"><textarea id="post-description" aria-label="Post description (optional)" placeholder="Description" rows="2">${esc(d.description)}</textarea></details><div class="post-compose-actions"><span id="post-upload-status" role="status"></span><button class="btn primary" id="publish-post" type="submit">${d.schedule?'Schedule':d.type==='live'?'Go live':'Post'}</button></div></form>`);document.querySelector('#modal').classList.add('publishing-dialog');document.querySelector('#modal').addEventListener('close',()=>{stopStreamPreview();document.querySelector('#modal').classList.remove('publishing-dialog')},{once:true});bindPublishing();drawPostAttachments();validatePostButton()}
function pollOptionInputs(){return publishingDraft.options.map((value,i)=>`<div class="poll-option-input"><input type="text" data-poll-option="${i}" aria-label="Poll option ${i+1}" placeholder="Option ${i+1}" value="${esc(value)}"><button type="button" data-remove-option="${i}" aria-label="Remove option ${i+1}" ${publishingDraft.options.length<=2?'disabled':''}>${icon('close')}</button></div>`).join('')}
function bindPollInputs(){document.querySelectorAll('[data-poll-option]').forEach(el=>el.oninput=()=>{publishingDraft.options[+el.dataset.pollOption]=el.value;savePublishingDraft();validatePostButton()});document.querySelectorAll('[data-remove-option]').forEach(el=>el.onclick=()=>{publishingDraft.options.splice(+el.dataset.removeOption,1);savePublishingDraft();document.querySelector('#poll-options').innerHTML=pollOptionInputs();bindPollInputs();validatePostButton()})}
function validatePostButton(){const d=publishingDraft,b=document.querySelector('#publish-post');if(!b)return;const has=d.text.trim()||d.title.trim()||d.description.trim()||d.attachments.length;b.disabled=!!uploadingPostFiles||!!(d.openSource&&(!d.license||!d.attachments.length))||(d.type==='poll'?(!d.question.trim()||d.options.some(o=>!o.trim())||d.options.length<2):d.type==='live'?!d.schedule:!has);b.textContent=d.schedule?'Schedule':d.type==='live'?'Go live':'Post';document.querySelector('#post-upload-status').textContent=uploadingPostFiles?'Adding files…':''}
async function addPostFiles(files){uploadingPostFiles+=files.length;validatePostButton();for(const file of files){try{const a={id:crypto.randomUUID(),name:file.name,type:file.type||'application/octet-stream',size:file.size,kind:'file'};await storeMedia(a.id,file);publishingDraft.attachments.push(a);savePublishingDraft()}catch(e){toast(e.name==='QuotaExceededError'?'Device storage is full. File not added.':'Could not add file')}finally{uploadingPostFiles--;if(document.querySelector('#post-attachment-list'))drawPostAttachments();validatePostButton()}}}
function drawPostAttachments(){const root=document.querySelector('#post-attachment-list');if(!root)return;root.innerHTML=publishingDraft.attachments.map((a,i)=>`<div class="post-file-draft">${attachmentView(a)}<button type="button" data-remove-post-file="${i}" aria-label="Remove ${esc(a.name)}">${icon('close')}</button></div>`).join('');root.querySelectorAll('[data-remove-post-file]').forEach(b=>b.onclick=()=>{publishingDraft.attachments.splice(+b.dataset.removePostFile,1);savePublishingDraft();drawPostAttachments();validatePostButton()});hydrateMedia(root)}
function bindPublishing(){document.querySelector('#post-open-source').onchange=e=>{publishingDraft.openSource=e.target.checked;document.querySelector('#post-license-panel').hidden=!e.target.checked;savePublishingDraft();validatePostButton()};document.querySelector('#post-license').onchange=e=>{publishingDraft.license=e.target.value;savePublishingDraft();validatePostButton()};for(const [id,key] of [['post-content','text'],['post-title','title'],['post-description','description'],['poll-question','question'],['post-schedule','schedule']]){const el=document.getElementById(id);if(el)el.oninput=()=>{publishingDraft[key]=el.value;savePublishingDraft();validatePostButton()}}document.querySelectorAll('[data-publish-type]').forEach(b=>b.onclick=()=>{publishingDraft.type=b.dataset.publishType;savePublishingDraft();stopStreamPreview();postComposer()});bindPollInputs();document.querySelector('#add-poll-option')?.addEventListener('click',()=>{publishingDraft.options.push('');savePublishingDraft();document.querySelector('#poll-options').innerHTML=pollOptionInputs();bindPollInputs();document.querySelector('[data-poll-option]:last-of-type')?.focus();validatePostButton()});document.querySelector('#post-attach').onclick=()=>document.querySelector('#post-file-input').click();document.querySelector('#post-file-input').onchange=e=>{addPostFiles([...e.target.files]);e.target.value=''};document.querySelector('#post-schedule-toggle').onclick=e=>{const panel=document.querySelector('#post-schedule-panel');panel.hidden=!panel.hidden;e.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)document.querySelector('#post-schedule').focus()};document.querySelector('#clear-schedule').onclick=()=>{publishingDraft.schedule='';document.querySelector('#post-schedule').value='';savePublishingDraft();validatePostButton()};document.querySelector('#preview-stream')?.addEventListener('click',async()=>{if(streamPreview){stopStreamPreview();return}const button=document.querySelector('#preview-stream');button.disabled=true;try{const type=document.querySelector('#stream-source').value,stream=type==='screen'?await navigator.mediaDevices.getDisplayMedia({video:true,audio:true}):await navigator.mediaDevices.getUserMedia({video:true,audio:true});const video=document.querySelector('#stream-preview');if(!video){stream.getTracks().forEach(t=>t.stop());return}streamPreview=stream;video.srcObject=stream;video.hidden=false;button.textContent='Stop preview';stream.getVideoTracks()[0].onended=stopStreamPreview}catch(e){toast(e.name==='NotAllowedError'?'Preview permission was not granted':'Preview unavailable')}finally{if(button.isConnected)button.disabled=false}});document.querySelector('#stream-source')?.addEventListener('change',stopStreamPreview);const form=document.querySelector('#post-form');form.ondragover=e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()};form.ondrop=e=>{e.preventDefault();addPostFiles([...e.dataTransfer.files])};form.onsubmit=e=>{e.preventDefault();submitPublication()}}
function submitPublication(){if(document.querySelector('#publish-post').disabled)return;const d=publishingDraft;let publishAt=null;try{publishAt=scheduleISO(d.schedule);if(publishAt&&new Date(publishAt)<=new Date())throw Error('Choose a future publish time')}catch(e){toast(e.message||'Invalid publish time');return}if(d.type==='live'&&!publishAt){toast('Streaming service not connected');return}ensureOwnSource();const post={id:Date.now(),source:'self',platform:'App',time:'Just now',title:d.title.trim(),text:d.text.trim(),description:d.description.trim(),attachments:d.attachments.slice(),openSource:!!d.openSource,license:d.openSource?d.license:null,contributions:[],type:d.type,status:publishAt?'scheduled':'published',publishAt,createdAt:new Date().toISOString()};if(d.type==='poll'){const options=d.options.map(o=>o.trim());if(new Set(options.map(o=>o.toLocaleLowerCase())).size!==options.length){toast('Poll options must be different');return}post.poll={question:d.question.trim(),options,vote:null}}ownPosts.unshift(post);if(!publishAt)posts.unshift(post);publishingDraft={type:'post',text:'',title:'',description:'',attachments:[],question:'',options:['',''],schedule:''};postDraft='';persist();document.querySelector('#modal').close();selectedSource='self';go('Source');sourceMode=publishAt?'Scheduled':'Updates';render();toast(publishAt?'Scheduled':'Posted')}
function publishDuePosts(){const now=Date.now();let changed=false;for(const p of ownPosts){if(p.status==='scheduled'&&new Date(p.publishAt).getTime()<=now){p.status='published';p.time='Just now';if(!posts.some(x=>x.id===p.id))posts.unshift(p);changed=true}}if(changed){persist();if(page==='Source'&&selectedSource==='self'&&sourceMode==='Scheduled')render()}}
function scheduledPostsView(){const list=ownPosts.filter(p=>p.status==='scheduled').sort((a,b)=>new Date(a.publishAt)-new Date(b.publishAt));return `<div class="scheduled-posts">${list.map(p=>`<details class="scheduled-item"><summary>${p.type==='live'?'Stream announcement':p.type==='poll'?'Poll':'Post'}<time>${esc(messageTime(p.publishAt))}</time></summary><div>${p.title?`<h3>${esc(p.title)}</h3>`:''}${p.text?`<p>${esc(p.text)}</p>`:''}${p.poll?`<p>${esc(p.poll.question)}</p>`:''}<button class="btn" data-reschedule="${p.id}">Reschedule</button></div></details>`).join('')||'<div class="empty">No scheduled posts</div>'}</div>`}
function pollMarkup(p){return p.poll?`<section class="post-poll"><h3>${esc(p.poll.question)}</h3>${p.poll.options.map((o,i)=>`<button type="button" data-poll-vote="${p.id}" data-vote-index="${i}" aria-pressed="${p.poll.vote===i}"><span>${esc(o)}</span>${p.poll.vote===i?icon('check'):''}</button>`).join('')}</section>`:''}
function bindPublicationView(root){root.querySelectorAll('[data-contribute-post]').forEach(b=>b.onclick=()=>contributePost(+b.dataset.contributePost));hydrateMedia(root);root.querySelectorAll('[data-post-media]').forEach(async el=>{try{el.src=await mediaUrl(el.dataset.postMedia)}catch{el.hidden=true}});root.querySelectorAll('[data-poll-vote]').forEach(b=>b.onclick=()=>{const p=ownPosts.find(p=>p.id===+b.dataset.pollVote);p.poll.vote=p.poll.vote===+b.dataset.voteIndex?null:+b.dataset.voteIndex;persist();const poll=root.querySelector('.post-poll');poll.outerHTML=pollMarkup(p);bindPublicationView(root)});document.querySelectorAll('[data-reschedule]').forEach(b=>b.onclick=()=>{const p=ownPosts.find(p=>p.id===+b.dataset.reschedule);modal('Reschedule',`<form id="reschedule-form"><label class="category-field">Publish time · ${esc(profile.timezone)}<input type="datetime-local" id="reschedule-time" required></label><button class="btn full">Save</button></form>`);document.querySelector('#reschedule-form').onsubmit=e=>{e.preventDefault();try{const date=scheduleISO(document.querySelector('#reschedule-time').value);if(new Date(date)<=new Date())throw Error('Choose a future publish time');p.publishAt=date;persist();document.querySelector('#modal').close();render()}catch(e){toast(e.message)}}})}
setInterval(publishDuePosts,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)publishDuePosts()});

function openSourceComposer(){const d=publishingDraft;return `<div class="open-source-composer"><label class="open-source-toggle"><input type="checkbox" id="post-open-source" ${d.openSource?'checked':''}>Open source</label><div id="post-license-panel" ${d.openSource?'':'hidden'}><label>License<select id="post-license" aria-label="Post license"><option value="">Choose a license</option>${['CC0 1.0','CC BY 4.0','MIT','Apache 2.0'].map(l=>`<option ${d.license===l?'selected':''}>${l}</option>`).join('')}</select></label></div></div>`}
function openSourcePost(p){if(!p.openSource)return '';return `<section class="open-source-post"><div><span>Open source</span><span class="post-license-label">${esc(p.license)}</span><button class="btn" data-contribute-post="${p.id}">${icon('plus')} Contribute files</button></div>${p.contributions?.length?`<details class="contribution-list"><summary>Contributions · ${p.contributions.length}</summary>${p.contributions.map(c=>`<article><header><strong>${esc(authorName(c.author))}</strong><time>${esc(messageTime(c.time))}</time><span>${c.status||'Submitted'}</span></header>${c.text?`<p>${esc(c.text)}</p>`:''}<div>${c.attachments.map(attachmentView).join('')}</div></article>`).join('')}</details>`:''}</section>`}
function contributePost(id){const p=ownPosts.find(p=>p.id===id);let files=[],busy=0;modal('Contribute files',`<form id="contribute-form"><textarea id="contribute-text" placeholder="Note (optional)" aria-label="Contribution note" rows="3"></textarea><input type="file" id="contribute-files" multiple hidden><button type="button" class="btn" id="choose-contribution">${icon('plus')} Files</button><div id="contribution-files"></div><div class="post-compose-actions"><span>${esc(p.license)}</span><button class="btn primary" id="submit-contribution" disabled>Submit</button></div></form>`);document.querySelector('#choose-contribution').onclick=()=>document.querySelector('#contribute-files').click();document.querySelector('#contribute-files').onchange=async e=>{const list=[...e.target.files];busy+=list.length;document.querySelector('#submit-contribution').disabled=true;for(const f of list){try{const a={id:crypto.randomUUID(),kind:'file',name:f.name,type:f.type||'application/octet-stream',size:f.size};await storeMedia(a.id,f);files.push(a)}catch{toast('Could not add file')}finally{busy--}}const root=document.querySelector('#contribution-files');if(root){root.innerHTML=files.map(attachmentView).join('');hydrateMedia(root);document.querySelector('#submit-contribution').disabled=busy>0||!files.length}};document.querySelector('#contribute-form').onsubmit=e=>{e.preventDefault();if(busy||!files.length)return;(p.contributions||=[]).push({id:crypto.randomUUID(),author:actorId,time:new Date().toISOString(),text:document.querySelector('#contribute-text').value.trim(),attachments:files,status:'Submitted'});persist();document.querySelector('#modal').close();const target=document.querySelector(`[data-post="${p.id}"] .update-content`);if(target){render();const item=document.querySelector(`[data-post="${p.id}"]`);if(item)item.open=true}toast('Contribution submitted')}}

document.addEventListener('keydown' ,e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();go('Search');document.querySelector('#search-input').focus()}});publishDuePosts();render();
